fn extract_rear_chars(s: &Vec<Vec<char>>) -> Vec<char> {
    // Pre-allocate result with the same length as `s`
    let mut result = Vec::with_capacity(s.len());
    // For each inner sequence, push its last character.
    for inner in s {
        // We know `inner` is non-empty, so `last()` is always `Some(&char)`.
        result.push(*inner.last().unwrap());
    }
    result
}

